import json
from collections import deque

# Compute which 5s are enclosed by 7s
# A 5 is enclosed if all paths to grid boundary go through 7s

rows, cols = 21, 15
grid = parse_grid()

# Flood fill from boundaries with color -1 to find "outside" region
enclosed = [[False] * cols for _ in range(rows)]  # True if 5 at (r,c) is enclosed

visited = [[False] * cols for _ in range(rows)]
queue = deque()

# Add all boundary cells
for r in range(rows):
    for c in [0, cols-1]:
        if grid[r][c] == 5:
            visited[r][c] = True
            queue.append((r, c))
for c in range(cols):
    for r in [0, rows-1]:
        if grid[r][c] == 5:
            visited[r][c] = True
            queue.append((r, c))

# Also add boundary cells that are 7 (they block flood fill)
# But we're only tracking where 5s are outside

directions = [(1,0), (-1,0), (0,1), (0,-1)]

while queue:
    r, c = queue.popleft()
    if visited[r][c]:
        continue
    visited[r][c] = True

    for dr, dc in directions:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            if not visited[nr][nc] and grid[nr][nc] == 5:
                visited[nr][nc] = True
                queue.append((nr, nc))

# Mark 5s that are NOT visited as enclosed
for r in range(rows):
    for c in range(cols):
        if grid[r][c] == 5:
            enclosed[r][c] = not visited[r][c]

# Now compute output: 7→0, 5→2 if enclosed, 5→5 if not enclosed?
# Or: 7→0, enclosed 5s → 2, outside 5s → 0?
# Or: 7→0, 5s outside → 5, 5s inside → 2?

# Let's try: 7→0, enclosed 5s → 2, outside 5s → 0
output = [[0 if grid[r][c] == 7 else (2 if enclosed[r][c] else 0) for c in range(cols)] for r in range(rows)]

print(json.dumps({"action": "submit", "grid": output}))

